import * as React from 'react';
import { useMemo, useState } from 'react';
import { Link, Route, Switch, useLocation, useParams } from 'wouter';
import {
  ArrowLeft, ArrowRight, BarChart3, Bell, BookOpen, Box, Check, ChevronDown, ChevronRight,
  CircleHelp, Clock3, CreditCard, Eye, Facebook, Filter, Heart, Home, MapPin, Menu, Minus,
  PackageCheck, Phone, Plus, Search, Settings, ShieldCheck, ShoppingCart, SlidersHorizontal,
  Sparkles, Star, Store, Tag, Trash2, Truck, UserRound, Wallet, Waves, X, Zap,
} from 'lucide-react';
import { applianceImages, articles, categories, orders, products, type Product } from '@/data/mock-data';

const money = (n: number) => n.toLocaleString('vi-VN') + '₫';
const pct = (n: Product) => Math.round((1 - n.price / n.oldPrice) * 100);
const findProduct = (id?: string) => products.find((item) => item.id === id) ?? products[0];

type CartItem = { product: Product; qty: number };
type StoreContext = {
  cart: CartItem[];
  wishlist: string[];
  compared: string[];
  toggleWishlist: (id: string) => void;
  toggleCompare: (id: string) => void;
  addToCart: (product: Product, qty?: number) => void;
  updateQty: (id: string, qty: number) => void;
  removeCart: (id: string) => void;
  openQuickView: (product: Product) => void;
};

function Header({ ctx }: { ctx: StoreContext }) {
  const [location, setLocation] = useLocation();
  const [search, setSearch] = useState('');
  const [focused, setFocused] = useState(false);
  const suggestions = products.filter((p) => `${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(search.toLowerCase())).slice(0, 5);
  const submitSearch = () => { if (search.trim()) setLocation(`/products?q=${encodeURIComponent(search.trim())}`); else setLocation('/products'); setFocused(false); };
  return (
    <>
      <div className="bg-[#073b86] text-white text-[11px] sm:text-xs">
        <div className="container-store flex h-8 items-center justify-between gap-3">
          <span className="hidden sm:inline">Hệ thống 28 cửa hàng · Miễn phí giao lắp nội thành</span>
          <span className="sm:hidden">Miễn phí giao lắp nội thành</span>
          <div className="flex items-center gap-4"><span className="hidden sm:inline">Trung tâm hỗ trợ</span><span>Hotline 1800 6865</span></div>
        </div>
      </div>
      <header className="sticky top-0 z-40 border-b border-[#dce5ef] bg-white/95 backdrop-blur">
        <div className="container-store flex h-[72px] items-center gap-3">
          <Link href="/" className="flex shrink-0 items-center gap-2" data-testid="link-logo">
            <span className="grid h-10 w-10 place-items-center bg-[#f6b91a] text-[#073b86]"><Zap size={22} fill="currentColor" /></span>
            <span className="hidden leading-none sm:block"><b className="font-display text-xl tracking-tight text-[#073b86]">ĐIỆN MÁY</b><br /><b className="text-[10px] tracking-[.24em] text-[#f09f14]">365</b></span>
          </Link>
          <button className="hidden h-10 items-center gap-2 border border-[#dce5ef] px-3 text-sm font-semibold text-[#173b68] lg:flex" onClick={() => setLocation('/products')} data-testid="button-category-menu"><Menu size={17} /> Danh mục</button>
          <div className="relative min-w-0 flex-1">
            <div className="flex h-11 overflow-hidden border-2 border-[#0b4fa4] bg-[#f5f8fc]">
              <input value={search} onChange={(e) => setSearch(e.target.value)} onFocus={() => setFocused(true)} onKeyDown={(e) => e.key === 'Enter' && submitSearch()} placeholder="Bạn đang tìm gì hôm nay?" className="min-w-0 flex-1 bg-transparent px-3 text-sm outline-none placeholder:text-[#7b8fa7]" data-testid="input-search" />
              <button className="grid w-12 shrink-0 place-items-center bg-[#0b4fa4] text-white transition hover:bg-[#073b86]" onClick={submitSearch} data-testid="button-search"><Search size={20} /></button>
            </div>
            {focused && search && (
              <div className="absolute left-0 right-12 top-12 z-50 border border-[#dce5ef] bg-white p-2 shadow-xl">
                <div className="px-2 py-1 text-[11px] font-bold uppercase tracking-wider text-[#8293a8]">Gợi ý tìm kiếm</div>
                {suggestions.length ? suggestions.map((p) => <button key={p.id} className="flex w-full items-center gap-2 px-2 py-2 text-left text-sm hover:bg-[#f1f6fb]" onClick={() => { setSearch(p.name); setLocation(`/products?q=${p.name}`); setFocused(false); }} data-testid={`suggestion-${p.id}`}><Search size={14} className="text-[#96a9bd]" /><span className="line-clamp-1">{p.name}</span></button>) : <div className="px-2 py-3 text-sm text-[#70839a]">Không tìm thấy gợi ý phù hợp</div>}
              </div>
            )}
          </div>
          <div className="hidden items-center gap-4 md:flex">
            <HeaderAction icon={<Store size={19} />} label="Cửa hàng" onClick={() => setLocation('/products')} test="button-stores" />
            <HeaderAction icon={<Heart size={19} />} label="Yêu thích" count={ctx.wishlist.length || undefined} onClick={() => setLocation('/account')} test="button-wishlist" />
            <HeaderAction icon={<ShoppingCart size={19} />} label="Giỏ hàng" count={ctx.cart.reduce((s, i) => s + i.qty, 0) || undefined} onClick={() => setLocation('/cart')} test="button-cart" />
            <HeaderAction icon={<UserRound size={19} />} label="Tài khoản" onClick={() => setLocation('/account')} test="button-account" />
          </div>
          <button className="grid h-10 w-10 shrink-0 place-items-center border border-[#dce5ef] text-[#073b86] md:hidden" onClick={() => setLocation('/cart')} data-testid="button-mobile-cart"><ShoppingCart size={19} /></button>
        </div>
        <nav className="hidden border-t border-[#edf1f6] lg:block">
          <div className="container-store flex h-11 items-center gap-7 text-sm font-semibold text-[#36526f]">
            <Link href="/products?category=air-conditioner" className="flex items-center gap-1 text-[#0b4fa4]" data-testid="link-nav-aircon">Điều hòa <ChevronDown size={14} /></Link>
            <Link href="/products?category=refrigerator" data-testid="link-nav-fridge">Tủ lạnh</Link>
            <Link href="/products?category=washing-machine" data-testid="link-nav-washer">Máy giặt</Link>
            <Link href="/products?category=television" data-testid="link-nav-tv">Tivi</Link>
            <Link href="/products?category=kitchen" data-testid="link-nav-kitchen">Nhà bếp</Link>
            <Link href="/products?sort=sale" className="text-[#c84b25]" data-testid="link-nav-sale">Khuyến mãi</Link>
            <Link href="/news" data-testid="link-nav-news">Kinh nghiệm hay</Link>
            <span className="ml-auto flex items-center gap-1 text-xs font-medium text-[#71869d]"><ShieldCheck size={15} className="text-[#1c8e6f]" /> Chính hãng · Đổi trả 30 ngày</span>
          </div>
        </nav>
      </header>
    </>
  );
}

function HeaderAction({ icon, label, count, onClick, test }: { icon: React.ReactNode; label: string; count?: number; onClick: () => void; test: string }) {
  return <button className="relative flex flex-col items-center gap-1 text-[11px] font-medium text-[#48647f] transition hover:text-[#0b4fa4]" onClick={onClick} data-testid={test}>{icon}<span>{label}</span>{count ? <span className="absolute -right-2 -top-2 grid h-4 min-w-4 place-items-center bg-[#e55937] px-1 text-[9px] font-bold text-white">{count}</span> : null}</button>;
}

function Footer() {
  return <footer className="mt-16 bg-[#082f69] text-white"><div className="container-store grid gap-10 py-12 sm:grid-cols-2 lg:grid-cols-4"><div><div className="mb-4 flex items-center gap-2"><span className="grid h-9 w-9 place-items-center bg-[#f6b91a] text-[#073b86]"><Zap size={19} fill="currentColor" /></span><b className="font-display text-lg">ĐIỆN MÁY 365</b></div><p className="text-sm leading-6 text-blue-100">Mua sắm điện máy chính hãng, giao nhanh tận nhà và lắp đặt tận tâm.</p><div className="mt-4 flex gap-2 text-blue-100"><Facebook size={17} /><Phone size={17} /><MessageIcon /></div></div><FooterCol title="Về Điện Máy 365" links={['Giới thiệu công ty', 'Hệ thống cửa hàng', 'Tuyển dụng', 'Tin tức công nghệ']} /><FooterCol title="Hỗ trợ khách hàng" links={['Chính sách giao hàng', 'Chính sách đổi trả', 'Bảo hành sản phẩm', 'Câu hỏi thường gặp']} /><div><b className="text-sm">Đăng ký nhận ưu đãi</b><p className="mt-3 text-sm text-blue-100">Mã giảm giá và tin mới, gửi vừa đủ.</p><div className="mt-4 flex border border-blue-300/40"><input className="min-w-0 flex-1 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-blue-200" placeholder="Email của bạn" data-testid="input-footer-email" /><button className="bg-[#f6b91a] px-3 text-sm font-bold text-[#082f69]" onClick={() => alert('Đã đăng ký nhận tin')} data-testid="button-footer-subscribe">Đăng ký</button></div></div></div><div className="border-t border-blue-300/20 py-5 text-center text-xs text-blue-200">© 2024 Điện Máy 365 · Nền tảng mua sắm điện máy của người Việt</div></footer>;
}
function MessageIcon() { return <span className="text-xs font-bold">Zalo</span>; }
function FooterCol({ title, links }: { title: string; links: string[] }) { return <div><b className="text-sm">{title}</b><div className="mt-4 space-y-3 text-sm text-blue-100">{links.map((x) => <button key={x} className="block transition hover:text-white" onClick={() => alert('Tính năng đang được cập nhật')} data-testid={`footer-${x}`}>{x}</button>)}</div></div>; }

function ProductCard({ product, ctx, compact = false }: { product: Product; ctx: StoreContext; compact?: boolean }) {
  const wished = ctx.wishlist.includes(product.id);
  const compared = ctx.compared.includes(product.id);
  return <article className={`group relative flex min-w-0 flex-col border border-[#e1e8f0] bg-white transition hover:-translate-y-0.5 hover:border-[#a8c3df] hover:shadow-[0_10px_26px_rgba(9,55,108,.10)] ${compact ? '' : 'fade-up'}`} data-testid={`card-product-${product.id}`}>
    <div className="relative aspect-[1.12] overflow-hidden bg-[#f5f8fb]"><img src={product.image} alt={product.name} className="h-full w-full object-cover mix-blend-multiply transition duration-500 group-hover:scale-[1.04]" /><div className="absolute left-2 top-2 flex flex-col gap-1">{product.badge && <span className="w-fit bg-[#e55937] px-2 py-1 text-[10px] font-bold text-white">{product.badge}</span>}<span className="w-fit bg-[#eaf3ff] px-2 py-1 text-[10px] font-semibold text-[#0b4fa4]">-{pct(product)}%</span></div><button className={`absolute right-2 top-2 grid h-8 w-8 place-items-center border bg-white/90 transition ${wished ? 'border-[#e55937] text-[#e55937]' : 'border-white text-[#657d99] hover:text-[#e55937]'}`} onClick={() => ctx.toggleWishlist(product.id)} data-testid={`button-wishlist-${product.id}`}><Heart size={16} fill={wished ? 'currentColor' : 'none'} /></button><button className="absolute bottom-2 right-2 grid h-8 w-8 translate-y-1 place-items-center bg-white/95 text-[#0b4fa4] opacity-0 shadow transition group-hover:translate-y-0 group-hover:opacity-100" onClick={() => ctx.openQuickView(product)} data-testid={`button-quickview-${product.id}`}><Eye size={16} /></button></div>
    <div className="flex flex-1 flex-col p-3"><div className="mb-1 text-[10px] font-bold uppercase tracking-wider text-[#8294a9]">{product.brand}</div><Link href={`/products/${product.id}`} className="line-clamp-2 min-h-[40px] text-sm font-semibold leading-5 text-[#183b62] hover:text-[#0b4fa4]" data-testid={`link-product-${product.id}`}>{product.name}</Link><div className="mt-2 flex items-center gap-1 text-xs"><Star size={13} fill="#f2ab18" className="text-[#f2ab18]" /><b>{product.rating}</b><span className="text-[#90a0b1]">({product.reviews})</span></div><div className="mt-auto pt-3"><div className="text-base font-extrabold text-[#d44b2e]">{money(product.price)}</div><div className="text-xs text-[#91a0b0] line-through">{money(product.oldPrice)}</div><div className="mt-2 flex items-center justify-between gap-2"><button className={`flex flex-1 items-center justify-center gap-1 border px-2 py-1.5 text-[11px] font-semibold transition ${compared ? 'border-[#0b4fa4] bg-[#eaf3ff] text-[#0b4fa4]' : 'border-[#d7e2ed] text-[#5e7792] hover:border-[#0b4fa4] hover:text-[#0b4fa4]'}`} onClick={() => ctx.toggleCompare(product.id)} data-testid={`button-compare-${product.id}`}><BarChart3 size={13} /> {compared ? 'Đã chọn' : 'So sánh'}</button><button className="grid h-8 w-8 place-items-center bg-[#0b4fa4] text-white transition hover:bg-[#073b86]" onClick={() => ctx.addToCart(product)} data-testid={`button-add-cart-${product.id}`}><ShoppingCart size={15} /></button></div></div></div>
  </article>;
}

function SectionTitle({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: string }) { return <div className="mb-5 flex items-end justify-between gap-3"><div>{eyebrow && <div className="mb-1 text-[11px] font-bold uppercase tracking-[.2em] text-[#c37c0c]">{eyebrow}</div>}<h2 className="font-display text-2xl font-bold tracking-tight text-[#14385f] sm:text-3xl">{title}</h2></div>{action && <Link href="/products" className="flex shrink-0 items-center gap-1 text-sm font-bold text-[#0b4fa4]" data-testid="link-section-action">{action} <ArrowRight size={16} /></Link>}</div>; }

function CategoryIcon({ category }: { category: (typeof categories)[number] }) { const Icon = category.icon === 'snowflake' ? Zap : category.icon === 'refrigerator' ? Box : category.icon === 'waves' ? Waves : category.icon === 'tv' ? Eye : category.icon === 'chef' ? Sparkles : category.icon === 'droplets' ? Waves : category.icon === 'wind' ? Zap : ShoppingCart; return <Icon size={24} />; }

function HomePage({ ctx }: { ctx: StoreContext }) {
  const [, setLocation] = useLocation();
  const featured = products.filter((p) => ['ac-02', 'rf-01', 'wm-01', 'tv-01', 'k-01', 'v-01'].includes(p.id));
  return <main><section className="bg-[#eaf3ff]"><div className="container-store grid min-h-[380px] items-center gap-8 py-10 md:grid-cols-[1.03fr_.97fr] md:py-14"><div className="fade-up"><div className="mb-4 inline-flex items-center gap-2 bg-[#d7e9ff] px-3 py-1.5 text-xs font-bold text-[#0b4fa4]"><Zap size={14} fill="currentColor" /> MÙA NÓNG, NHÀ MÁT</div><h1 className="max-w-xl font-display text-4xl font-bold leading-[1.03] tracking-[-.04em] text-[#0a356d] sm:text-6xl">Mát nhà.<br /><span className="text-[#e29b12]">Nhẹ ví.</span> Sống vui.</h1><p className="mt-5 max-w-md text-base leading-7 text-[#466583]">Điều hòa Inverter chính hãng giảm đến 25%, giao lắp trong ngày tại 28 tỉnh thành.</p><div className="mt-7 flex flex-wrap gap-3"><Link href="/products?category=air-conditioner" className="inline-flex items-center gap-2 bg-[#0b4fa4] px-5 py-3 text-sm font-bold text-white shadow-lg shadow-blue-900/15 transition hover:bg-[#073b86]" data-testid="link-hero-shop">Xem điều hòa bán chạy <ArrowRight size={17} /></Link><Link href="/products" className="inline-flex items-center gap-2 border border-[#9dbbda] bg-white/50 px-5 py-3 text-sm font-bold text-[#0b4fa4]" data-testid="link-hero-all">Khám phá sản phẩm</Link></div><div className="mt-8 flex gap-5 text-xs font-semibold text-[#52718f]"><span className="flex items-center gap-1.5"><ShieldCheck size={16} className="text-[#1a8d6d]" /> Chính hãng 100%</span><span className="flex items-center gap-1.5"><Truck size={16} className="text-[#1a8d6d]" /> Lắp đặt tận tâm</span></div></div><div className="relative flex min-h-[270px] items-center justify-center md:min-h-[330px]"><div className="absolute right-4 top-4 h-52 w-52 rounded-full bg-[#cfe3fb] blur-[1px] sm:h-72 sm:w-72"></div><div className="absolute bottom-2 left-6 h-24 w-32 border-b-2 border-l-2 border-[#9cc1e8]"></div><img src={applianceImages[0]} alt="Điều hòa Daikin" className="relative z-10 h-[270px] w-full max-w-[470px] object-cover mix-blend-multiply drop-shadow-2xl sm:h-[330px]" /><div className="absolute bottom-4 right-3 z-20 bg-white p-3 shadow-xl sm:right-10"><div className="text-[10px] font-bold uppercase tracking-wider text-[#8294a9]">Deal hôm nay</div><b className="text-lg text-[#d44b2e]">Giảm đến 25%</b></div></div></div></section>
    <div className="border-b border-[#e1e8f0] bg-white"><div className="container-store grid grid-cols-2 divide-x divide-[#e5ebf2] py-4 sm:grid-cols-4"><Trust icon={<Truck size={20} />} title="Giao nhanh tận nhà" sub="Đúng hẹn, đúng phí" /><Trust icon={<Settings size={20} />} title="Lắp đặt chuyên nghiệp" sub="Kỹ thuật viên 4.9/5" /><Trust icon={<ShieldCheck size={20} />} title="Bảo hành chính hãng" sub="An tâm sử dụng" /><Trust icon={<CircleHelp size={20} />} title="Hỗ trợ 7 ngày/tuần" sub="1800 6865 miễn phí" /></div></div>
    <div className="container-store py-12"><SectionTitle eyebrow="Mua sắm theo nhu cầu" title="Bạn đang tìm gì?" /><div className="no-scrollbar grid grid-cols-2 gap-3 overflow-x-auto sm:grid-cols-5 lg:grid-cols-10">{categories.map((c, i) => <Link href={`/products?category=${c.id}`} key={c.id} className={`group flex min-h-[118px] flex-col items-center justify-center gap-3 border border-[#e1e8f0] bg-white p-3 text-center transition hover:-translate-y-1 hover:border-[#8eb4db] hover:shadow-md ${i > 5 ? 'hidden lg:flex' : ''}`} data-testid={`link-category-${c.id}`}><span className="grid h-12 w-12 place-items-center bg-[#eef5fd] text-[#0b4fa4] transition group-hover:bg-[#d9eaff]"><CategoryIcon category={c} /></span><span className="text-xs font-bold text-[#335474]">{c.name}</span><span className="text-[10px] text-[#91a0b0]">{c.count} sản phẩm</span></Link>)}</div></div>
    <section className="bg-[#0b4fa4] py-11 text-white"><div className="container-store"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="mb-1 flex items-center gap-2 text-xs font-bold uppercase tracking-[.2em] text-[#f7cc5d]"><Zap size={14} fill="currentColor" /> Chỉ trong hôm nay</div><h2 className="font-display text-3xl font-bold">Flash sale giờ vàng</h2></div><Countdown /><Link href="/products?sort=sale" className="hidden items-center gap-1 border border-blue-200/40 px-4 py-2 text-sm font-semibold sm:flex" data-testid="link-flash-sale">Xem tất cả <ArrowRight size={16} /></Link></div><div className="mt-6 grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-6">{featured.map((p) => <ProductCard key={p.id} product={p} ctx={ctx} compact />)}</div></div></section>
    <div className="container-store py-14"><SectionTitle eyebrow="Được chọn nhiều nhất" title="Sản phẩm bán chạy" action="Xem toàn bộ" /><div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">{products.slice(0, 10).map((p) => <ProductCard key={p.id} product={p} ctx={ctx} />)}</div></div>
    <section className="border-y border-[#dce7f2] bg-[#f5f9fd] py-12"><div className="container-store grid items-center gap-8 lg:grid-cols-[.8fr_1.2fr]"><div><div className="mb-2 text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">Đối tác tin cậy</div><h2 className="font-display text-3xl font-bold text-[#14385f]">Thương hiệu<br />làm nên chất lượng.</h2><p className="mt-4 max-w-sm text-sm leading-6 text-[#617992]">Tất cả sản phẩm đều có nguồn gốc rõ ràng, bảo hành chính hãng và đội ngũ kỹ thuật đồng hành.</p></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{['DAIKIN', 'Panasonic', 'SAMSUNG', 'LG', 'CASPER', 'TOSHIBA', 'AQUA', 'SHARP'].map((brand) => <button key={brand} className="grid h-20 place-items-center border border-[#dce7f2] bg-white font-display text-lg font-bold tracking-tight text-[#52708d] transition hover:border-[#8eb4db] hover:text-[#0b4fa4]" onClick={() => setLocation(`/products?q=${brand}`)} data-testid={`button-brand-${brand}`}>{brand}</button>)}</div></div></section>
    <div className="container-store py-14"><SectionTitle eyebrow="Góc Điện Máy 365" title="Mua đúng, dùng hay" action="Đọc tất cả" /><div className="grid gap-4 md:grid-cols-3">{articles.slice(0, 3).map((a, i) => <Link href={`/news/${a.id}`} key={a.id} className={`group flex gap-4 border-b border-[#dce5ef] pb-4 ${i === 0 ? 'md:col-span-2 md:grid md:grid-cols-2 md:border-b-0 md:pb-0' : ''}`} data-testid={`link-home-article-${a.id}`}><img src={a.image} alt="" className={`h-28 w-36 shrink-0 object-cover grayscale-[15%] transition group-hover:grayscale-0 ${i === 0 ? 'md:h-full md:w-full' : ''}`} /><div className="py-1"><div className="text-[10px] font-bold uppercase tracking-wider text-[#c37c0c]">{a.category}</div><h3 className="mt-2 line-clamp-2 font-display text-base font-bold leading-5 text-[#173b62] group-hover:text-[#0b4fa4]">{a.title}</h3><p className="mt-2 hidden text-xs leading-5 text-[#71869d] sm:block">{a.excerpt}</p><div className="mt-3 text-[11px] text-[#8293a8]">{a.date} · {a.read} đọc</div></div></Link>)}</div></div>
  </main>;
}
function Trust({ icon, title, sub }: { icon: React.ReactNode; title: string; sub: string }) { return <div className="flex items-center gap-3 px-3 first:pl-0 last:pr-0"><span className="text-[#0b4fa4]">{icon}</span><div><b className="block text-xs text-[#274b70] sm:text-sm">{title}</b><span className="text-[10px] text-[#8293a8] sm:text-xs">{sub}</span></div></div>; }
function Countdown() { const [left] = useState({ h: '05', m: '42', s: '18' }); return <div className="flex items-center gap-2"><Clock3 size={17} className="text-[#f7cc5d]" /><div className="flex items-center gap-1 font-mono text-lg font-bold"><span className="bg-[#073b86] px-2 py-1">{left.h}</span>:<span className="bg-[#073b86] px-2 py-1">{left.m}</span>:<span className="bg-[#073b86] px-2 py-1">{left.s}</span></div></div>; }

function ProductsPage({ ctx }: { ctx: StoreContext }) {
  const [loc, setLoc] = useLocation();
  const params = new URLSearchParams(loc.split('?')[1] || '');
  const query = params.get('q') || '';
  const initialCategory = params.get('category') || 'all';
  const [category, setCategory] = useState(initialCategory);
  const [sort, setSort] = useState(params.get('sort') === 'sale' ? 'sale' : 'popular');
  const [brand, setBrand] = useState('');
  const [btu, setBtu] = useState('');
  const [inverter, setInverter] = useState(false);
  const [mobileFilter, setMobileFilter] = useState(false);
  const filtered = useMemo(() => products.filter((p) => (!query || `${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(query.toLowerCase())) && (category === 'all' || p.categoryId === category) && (!brand || p.brand === brand) && (!btu || p.tags.includes(btu)) && (!inverter || p.tags.includes('Inverter'))).sort((a, b) => sort === 'price-low' ? a.price - b.price : sort === 'price-high' ? b.price - a.price : sort === 'sale' ? b.discount - a.discount : b.sold - a.sold), [query, category, brand, btu, inverter, sort]);
  const FilterPane = () => <div className="space-y-6"><div><b className="text-sm text-[#214665]">Danh mục</b><div className="mt-3 space-y-2">{categories.slice(0, 8).map((c) => <label key={c.id} className="flex cursor-pointer items-center justify-between text-sm text-[#5c7691]"><span className="flex items-center gap-2"><input type="radio" checked={category === c.id} onChange={() => setCategory(c.id)} className="accent-[#0b4fa4]" />{c.name}</span><span className="text-xs text-[#9aa8b8]">{c.count}</span></label>)}</div></div><div><b className="text-sm text-[#214665]">Thương hiệu</b><div className="mt-3 space-y-2">{['Daikin', 'Panasonic', 'LG', 'Samsung', 'Casper', 'Mitsubishi Electric', 'Toshiba', 'Aqua', 'Sharp'].map((b) => <label key={b} className="flex cursor-pointer items-center gap-2 text-sm text-[#5c7691]"><input type="radio" name="brand" checked={brand === b} onChange={() => setBrand(b)} className="accent-[#0b4fa4]" />{b}</label>)}</div></div><div><b className="text-sm text-[#214665]">Khoảng giá</b><div className="mt-3 grid grid-cols-2 gap-2"><input placeholder="Từ" className="w-full border border-[#dbe5ef] px-2 py-2 text-xs outline-none" data-testid="input-price-min" /><input placeholder="Đến" className="w-full border border-[#dbe5ef] px-2 py-2 text-xs outline-none" data-testid="input-price-max" /></div></div>{(category === 'air-conditioner' || query.toLowerCase().includes('điều hòa')) && <div className="border-t border-[#e1e8f0] pt-5"><b className="text-sm text-[#214665]">Lọc riêng cho điều hòa</b><div className="mt-3 space-y-3"><select value={btu} onChange={(e) => setBtu(e.target.value)} className="w-full border border-[#dbe5ef] bg-white px-2 py-2 text-sm outline-none" data-testid="select-btu"><option value="">Công suất BTU</option><option>9.000 BTU</option><option>12.000 BTU</option><option>18.000 BTU</option></select><label className="flex items-center gap-2 text-sm text-[#5c7691]"><input type="checkbox" checked={inverter} onChange={(e) => setInverter(e.target.checked)} className="accent-[#0b4fa4]" /> Chỉ Inverter</label></div></div>}<button className="w-full border border-[#cbd9e7] py-2 text-sm font-bold text-[#0b4fa4]" onClick={() => { setCategory('all'); setBrand(''); setBtu(''); setInverter(false); }} data-testid="button-clear-filters">Xóa bộ lọc</button></div>;
  return <main className="container-store py-7"><div className="mb-5 flex items-center gap-2 text-xs text-[#8293a8]"><Link href="/" className="hover:text-[#0b4fa4]" data-testid="link-breadcrumb-home">Trang chủ</Link><ChevronRight size={14} /><span>Sản phẩm</span>{query && <><ChevronRight size={14} /><b className="text-[#214665]">“{query}”</b></>}</div><div className="mb-8 border-b border-[#dce5ef] pb-7"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="mb-1 text-xs font-bold uppercase tracking-[.18em] text-[#c37c0c]">Danh mục sản phẩm</div><h1 className="font-display text-3xl font-bold tracking-tight text-[#14385f] sm:text-4xl">{query ? `Kết quả cho “${query}”` : category === 'all' ? 'Tất cả sản phẩm' : categories.find((x) => x.id === category)?.name}</h1><p className="mt-2 text-sm text-[#71869d]">{filtered.length} sản phẩm chính hãng · Giao nhanh, lắp đặt tận tâm</p></div><button className="flex items-center gap-2 border border-[#cbd9e7] px-3 py-2 text-sm font-semibold text-[#315575] lg:hidden" onClick={() => setMobileFilter(true)} data-testid="button-mobile-filter"><SlidersHorizontal size={16} /> Bộ lọc</button></div></div><div className="grid gap-8 lg:grid-cols-[225px_1fr]"><aside className="hidden lg:block"><FilterPane /></aside><div><div className="mb-5 flex items-center justify-between border-b border-[#e1e8f0] pb-3"><span className="text-sm text-[#71869d]">Hiển thị <b className="text-[#214665]">{filtered.length}</b> sản phẩm</span><select value={sort} onChange={(e) => setSort(e.target.value)} className="border border-[#dbe5ef] bg-white px-3 py-2 text-xs font-semibold text-[#36526f] outline-none" data-testid="select-sort"><option value="popular">Phổ biến nhất</option><option value="sale">Ưu đãi tốt nhất</option><option value="price-low">Giá thấp đến cao</option><option value="price-high">Giá cao đến thấp</option></select></div>{filtered.length ? <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-4">{filtered.map((p) => <ProductCard key={p.id} product={p} ctx={ctx} />)}</div> : <EmptyState onClear={() => { setCategory('all'); setBrand(''); setBtu(''); setInverter(false); }} />}</div></div>{mobileFilter && <div className="fixed inset-0 z-50 bg-[#102c4b]/30 lg:hidden" onClick={() => setMobileFilter(false)}><div className="absolute bottom-0 left-0 right-0 max-h-[85vh] overflow-y-auto bg-white p-5" onClick={(e) => e.stopPropagation()}><div className="mb-5 flex items-center justify-between"><b className="font-display text-xl text-[#173b62]">Bộ lọc sản phẩm</b><button onClick={() => setMobileFilter(false)} data-testid="button-close-filter"><X /></button></div><FilterPane /><button className="mt-5 w-full bg-[#0b4fa4] py-3 font-bold text-white" onClick={() => setMobileFilter(false)} data-testid="button-apply-filter">Xem kết quả</button></div></div>}</main>;
}
function EmptyState({ onClear }: { onClear: () => void }) { return <div className="flex min-h-[360px] flex-col items-center justify-center border border-dashed border-[#b9ccdf] bg-[#f7fafd] p-8 text-center"><Search size={38} className="text-[#8da9c5]" /><h3 className="mt-4 font-display text-xl font-bold text-[#214665]">Chưa có sản phẩm phù hợp</h3><p className="mt-2 max-w-sm text-sm text-[#70839a]">Thử bỏ bớt bộ lọc hoặc tìm kiếm bằng tên sản phẩm khác.</p><button onClick={onClear} className="mt-5 border border-[#0b4fa4] px-4 py-2 text-sm font-bold text-[#0b4fa4]" data-testid="button-empty-clear">Xóa bộ lọc</button></div>; }

function ProductDetail({ ctx }: { ctx: StoreContext }) {
  const { id } = useParams<{ id: string }>(); const product = findProduct(id); const [image, setImage] = useState(product.image); const [qty, setQty] = useState(1); const [tab, setTab] = useState('specs'); const [added, setAdded] = useState(false);
  const add = () => { ctx.addToCart(product, qty); setAdded(true); setTimeout(() => setAdded(false), 1700); };
  return <main className="container-store py-7"><div className="mb-5 flex items-center gap-2 text-xs text-[#8293a8]"><Link href="/products" data-testid="link-detail-back">Sản phẩm</Link><ChevronRight size={14} /><span>{product.category}</span><ChevronRight size={14} /><b className="line-clamp-1 text-[#214665]">{product.name}</b></div><div className="grid gap-9 lg:grid-cols-[1fr_1fr]"><div className="grid gap-3 sm:grid-cols-[76px_1fr]"><div className="order-2 flex gap-2 overflow-x-auto sm:order-1 sm:flex-col">{product.gallery.map((g, i) => <button key={g} onClick={() => setImage(g)} className={`h-16 w-16 shrink-0 overflow-hidden border-2 bg-[#f4f8fc] ${image === g ? 'border-[#0b4fa4]' : 'border-transparent'}`} data-testid={`button-gallery-${i}`}><img src={g} alt="" className="h-full w-full object-cover mix-blend-multiply" /></button>)}</div><div className="relative order-1 flex aspect-square items-center justify-center overflow-hidden bg-[#f4f8fc] sm:order-2"><img src={image} alt={product.name} className="h-full w-full object-cover mix-blend-multiply" /><span className="absolute bottom-3 left-3 flex items-center gap-1 bg-white/85 px-2 py-1 text-[10px] font-semibold text-[#607991]"><Eye size={13} /> Di chuột để phóng to</span></div></div><div><div className="text-xs font-bold uppercase tracking-[.2em] text-[#8294a9]">{product.brand} · {product.category}</div><h1 className="mt-2 font-display text-2xl font-bold leading-tight text-[#14385f] sm:text-3xl">{product.name}</h1><div className="mt-3 flex flex-wrap items-center gap-3 text-sm"><span className="flex items-center gap-1 font-bold"><Star size={16} fill="#f2ab18" className="text-[#f2ab18]" /> {product.rating}</span><span className="text-[#90a0b1]">|</span><span className="text-[#5e7792]">{product.reviews} đánh giá</span><span className="bg-[#edf7f2] px-2 py-1 text-xs font-bold text-[#168265]">Đã kiểm chứng</span></div><div className="mt-6 border-y border-[#e1e8f0] py-5"><div className="flex items-end gap-3"><span className="text-3xl font-extrabold text-[#d44b2e]">{money(product.price)}</span><span className="text-sm text-[#94a2b0] line-through">{money(product.oldPrice)}</span><span className="bg-[#fff0e9] px-2 py-1 text-xs font-bold text-[#d44b2e]">-{pct(product)}%</span></div><p className="mt-2 text-xs text-[#71869d]">Giá đã gồm VAT · Trả góp 0% qua thẻ tín dụng</p></div><div className="mt-5 space-y-3"><b className="text-sm text-[#214665]">Điểm nổi bật</b>{product.specs.slice(0, 3).map((s) => <div key={s.label} className="flex items-center justify-between border-b border-dashed border-[#e1e8f0] py-2 text-sm"><span className="text-[#71869d]">{s.label}</span><b className="text-[#315575]">{s.value}</b></div>)}</div><div className="mt-5 flex items-center gap-3"><span className="text-sm font-semibold text-[#315575]">Số lượng</span><div className="flex border border-[#d5e1ec]"><button className="grid h-9 w-9 place-items-center text-[#315575]" onClick={() => setQty(Math.max(1, qty - 1))} data-testid="button-qty-minus"><Minus size={14} /></button><span className="grid h-9 w-9 place-items-center text-sm font-bold">{qty}</span><button className="grid h-9 w-9 place-items-center text-[#315575]" onClick={() => setQty(qty + 1)} data-testid="button-qty-plus"><Plus size={14} /></button></div><span className="text-xs text-[#168265]">Còn {product.stock} sản phẩm</span></div><div className="mt-5 flex gap-2"><button className="flex flex-1 items-center justify-center gap-2 border-2 border-[#0b4fa4] py-3 text-sm font-bold text-[#0b4fa4]" onClick={add} data-testid="button-detail-add-cart"><ShoppingCart size={18} /> {added ? 'Đã thêm vào giỏ' : 'Thêm vào giỏ'}</button><button className="flex-1 bg-[#e65a37] py-3 text-sm font-bold text-white transition hover:bg-[#cb4726]" onClick={() => { add(); setTimeout(() => window.location.href = '/checkout', 250); }} data-testid="button-buy-now">Mua ngay</button></div><div className="mt-3 flex gap-2"><button className={`flex flex-1 items-center justify-center gap-2 border py-2 text-xs font-bold ${ctx.compared.includes(product.id) ? 'border-[#0b4fa4] bg-[#edf5ff] text-[#0b4fa4]' : 'border-[#d5e1ec] text-[#5e7792]'}`} onClick={() => ctx.toggleCompare(product.id)} data-testid="button-detail-compare"><BarChart3 size={14} /> {ctx.compared.includes(product.id) ? 'Đã thêm so sánh' : 'Thêm vào so sánh'}</button><button className="flex items-center gap-2 border border-[#d5e1ec] px-4 py-2 text-xs font-bold text-[#5e7792]" onClick={() => ctx.toggleWishlist(product.id)} data-testid="button-detail-wishlist"><Heart size={14} fill={ctx.wishlist.includes(product.id) ? 'currentColor' : 'none'} /> Yêu thích</button></div></div></div><div className="mt-12 border-y border-[#dce5ef]"><div className="flex gap-5 overflow-x-auto">{[['specs', 'Thông số kỹ thuật'], ['delivery', 'Giao hàng & lắp đặt'], ['warranty', 'Bảo hành'], ['reviews', `Đánh giá (${product.reviews})`]].map(([key, label]) => <button key={key} className={`shrink-0 border-b-2 px-1 py-4 text-sm font-bold ${tab === key ? 'border-[#0b4fa4] text-[#0b4fa4]' : 'border-transparent text-[#71869d]'}`} onClick={() => setTab(key)} data-testid={`button-detail-tab-${key}`}>{label}</button>)}</div><div className="grid gap-8 py-7 md:grid-cols-2">{tab === 'specs' ? <div className="space-y-0">{product.specs.concat([{ label: 'Xuất xứ', value: 'Chính hãng Việt Nam' }, { label: 'Tình trạng', value: 'Mới 100%' }]).map((s) => <div key={s.label} className="flex border-b border-[#edf1f5] py-3 text-sm"><span className="w-1/2 text-[#71869d]">{s.label}</span><b className="text-[#315575]">{s.value}</b></div>)}</div> : <div className="max-w-xl text-sm leading-7 text-[#5e7792]">{tab === 'delivery' && 'Miễn phí giao hàng trong bán kính 20 km. Dịch vụ lắp đặt tiêu chuẩn được đặt lịch ngay trong bước thanh toán, kỹ thuật viên gọi xác nhận trước khi đến.'}{tab === 'warranty' && 'Sản phẩm được bảo hành chính hãng 12 tháng. Đổi mới trong 30 ngày đầu nếu có lỗi từ nhà sản xuất. Điện Máy 365 hỗ trợ tiếp nhận tận nơi.'}{tab === 'reviews' && 'Khách hàng đánh giá sản phẩm vận hành êm, làm lạnh nhanh và tiết kiệm điện. 94% khách hàng sẵn sàng giới thiệu sản phẩm này.'}</div>}<div className="bg-[#f4f8fc] p-5"><div className="flex items-center gap-3"><ShieldCheck className="text-[#168265]" /><div><b className="text-sm text-[#214665]">Mua hàng an tâm</b><p className="mt-1 text-xs leading-5 text-[#71869d]">Hàng chính hãng, kiểm tra trước khi nhận. Hỗ trợ đổi trả minh bạch.</p></div></div></div></div></div><div className="mt-12"><SectionTitle title="Có thể bạn cũng thích" action="Xem thêm" /><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{products.filter((p) => p.categoryId === product.categoryId && p.id !== product.id).slice(0, 4).map((p) => <ProductCard key={p.id} product={p} ctx={ctx} />)}</div></div></main>;
}

function ComparePage({ ctx }: { ctx: StoreContext }) {
  const selected = ctx.compared.map(findProduct).slice(0, 4); const slots = [...selected, ...Array(Math.max(0, 4 - selected.length)).fill(null)];
  return <main className="container-store py-8"><div className="mb-7"><div className="mb-1 text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">Quyết định dễ hơn</div><h1 className="font-display text-3xl font-bold text-[#14385f] sm:text-4xl">So sánh sản phẩm</h1><p className="mt-2 text-sm text-[#71869d]">Chọn tối đa 4 sản phẩm để xem điểm khác biệt.</p></div>{selected.length < 2 ? <div className="flex min-h-[330px] flex-col items-center justify-center border border-dashed border-[#b9ccdf] bg-white text-center"><BarChart3 size={42} className="text-[#7ea5ca]" /><h2 className="mt-4 font-display text-xl font-bold text-[#214665]">Bắt đầu bảng so sánh của bạn</h2><p className="mt-2 max-w-sm text-sm text-[#71869d]">Thêm ít nhất 2 sản phẩm từ danh sách hoặc trang chi tiết.</p><Link href="/products" className="mt-5 bg-[#0b4fa4] px-5 py-3 text-sm font-bold text-white" data-testid="link-compare-products">Chọn sản phẩm</Link></div> : <div className="overflow-x-auto border border-[#dce5ef] bg-white"><div className="grid min-w-[760px] grid-cols-[150px_repeat(4,1fr)]">{slots.map((p, i) => p ? <div key={p.id} className="relative border-b border-l border-[#e1e8f0] p-4"><button className="absolute right-2 top-2 text-[#9aa8b8] hover:text-[#d44b2e]" onClick={() => ctx.toggleCompare(p.id)} data-testid={`button-remove-compare-${p.id}`}><X size={15} /></button><img src={p.image} alt="" className="mx-auto aspect-square w-full max-w-[150px] object-cover mix-blend-multiply" /><div className="mt-3 text-[10px] font-bold uppercase tracking-wider text-[#8294a9]">{p.brand}</div><Link href={`/products/${p.id}`} className="mt-1 block line-clamp-2 text-sm font-bold leading-5 text-[#214665]" data-testid={`link-compare-product-${p.id}`}>{p.name}</Link><div className="mt-3 font-extrabold text-[#d44b2e]">{money(p.price)}</div><button className="mt-3 w-full bg-[#0b4fa4] py-2 text-xs font-bold text-white" onClick={() => ctx.addToCart(p)} data-testid={`button-compare-cart-${p.id}`}>Thêm vào giỏ</button></div> : <Link key={`empty-${i}`} href="/products" className="flex min-h-[260px] flex-col items-center justify-center border-b border-l border-[#e1e8f0] text-center text-sm text-[#7b91a7]" data-testid={`link-compare-empty-${i}`}><Plus size={22} className="mb-2 text-[#0b4fa4]" />Thêm sản phẩm</Link>)}{['Thương hiệu', 'Đánh giá', 'Công nghệ', 'Công suất / kích thước', 'Bảo hành', 'Giao hàng'].map((label, row) => <div key={label} className="contents"><div className="bg-[#f5f8fc] p-4 text-xs font-bold text-[#607991]">{label}</div>{slots.map((p, i) => <div key={`${label}-${i}`} className="border-l border-t border-[#e1e8f0] p-4 text-sm text-[#315575]">{p ? label === 'Thương hiệu' ? p.brand : label === 'Đánh giá' ? <span className="flex items-center gap-1"><Star size={14} fill="#f2ab18" className="text-[#f2ab18]" /> {p.rating} ({p.reviews})</span> : label === 'Công nghệ' ? p.specs[1]?.value : label === 'Bảo hành' ? '12 tháng' : label === 'Giao hàng' ? 'Miễn phí' : p.specs[0]?.value : '—'}</div>)}</div>)}</div></div>}</main>;
}

function CartPage({ ctx }: { ctx: StoreContext }) {
  const subtotal = ctx.cart.reduce((s, i) => s + i.product.price * i.qty, 0); const shipping = subtotal > 10000000 || subtotal === 0 ? 0 : 35000; const total = subtotal + shipping;
  return <main className="container-store py-8"><div className="mb-7"><div className="mb-1 text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">Kiểm tra lại lựa chọn</div><h1 className="font-display text-3xl font-bold text-[#14385f]">Giỏ hàng <span className="text-lg font-medium text-[#8293a8]">({ctx.cart.reduce((s, i) => s + i.qty, 0)} sản phẩm)</span></h1></div>{!ctx.cart.length ? <div className="flex min-h-[360px] flex-col items-center justify-center border border-dashed border-[#b9ccdf] bg-white text-center"><ShoppingCart size={42} className="text-[#7ea5ca]" /><h2 className="mt-4 font-display text-xl font-bold text-[#214665]">Giỏ hàng đang trống</h2><p className="mt-2 text-sm text-[#71869d]">Thêm sản phẩm bạn thích để bắt đầu.</p><Link href="/products" className="mt-5 bg-[#0b4fa4] px-5 py-3 text-sm font-bold text-white" data-testid="link-empty-cart">Tiếp tục mua sắm</Link></div> : <div className="grid gap-7 lg:grid-cols-[1fr_360px]"><div className="border border-[#dce5ef] bg-white">{ctx.cart.map(({ product, qty }) => <div key={product.id} className="flex gap-3 border-b border-[#e5ebf2] p-4 last:border-b-0 sm:gap-5"><img src={product.image} alt="" className="h-24 w-24 shrink-0 object-cover mix-blend-multiply sm:h-32 sm:w-32" /><div className="min-w-0 flex-1"><div className="text-[10px] font-bold uppercase tracking-wider text-[#8294a9]">{product.brand}</div><Link href={`/products/${product.id}`} className="mt-1 block line-clamp-2 text-sm font-bold text-[#214665]" data-testid={`link-cart-product-${product.id}`}>{product.name}</Link><div className="mt-2 text-base font-extrabold text-[#d44b2e]">{money(product.price)}</div><div className="mt-3 flex items-center justify-between gap-3"><div className="flex border border-[#d5e1ec]"><button className="grid h-8 w-8 place-items-center" onClick={() => ctx.updateQty(product.id, qty - 1)} data-testid={`button-cart-minus-${product.id}`}><Minus size={13} /></button><span className="grid h-8 w-8 place-items-center text-sm">{qty}</span><button className="grid h-8 w-8 place-items-center" onClick={() => ctx.updateQty(product.id, qty + 1)} data-testid={`button-cart-plus-${product.id}`}><Plus size={13} /></button></div><button className="flex items-center gap-1 text-xs font-semibold text-[#8293a8] hover:text-[#d44b2e]" onClick={() => ctx.removeCart(product.id)} data-testid={`button-remove-cart-${product.id}`}><Trash2 size={14} /> Xóa</button></div></div><div className="hidden text-right sm:block"><b className="text-base text-[#214665]">{money(product.price * qty)}</b><div className="mt-2 text-xs text-[#168265]">Còn hàng</div></div></div>)}<div className="flex items-center justify-between bg-[#f5f8fc] p-4 text-sm"><Link href="/products" className="flex items-center gap-1 font-semibold text-[#0b4fa4]" data-testid="link-cart-continue"><ArrowLeft size={15} /> Tiếp tục mua sắm</Link><span className="text-[#71869d]">Đã bao gồm VAT</span></div></div><div className="h-fit border border-[#dce5ef] bg-white p-5"><h2 className="font-display text-lg font-bold text-[#214665]">Tóm tắt đơn hàng</h2><div className="mt-5 space-y-3 border-b border-[#e1e8f0] pb-5 text-sm"><div className="flex justify-between text-[#71869d]"><span>Tạm tính</span><b className="text-[#315575]">{money(subtotal)}</b></div><div className="flex justify-between text-[#71869d]"><span>Phí giao hàng</span><b className="text-[#168265]">{shipping ? money(shipping) : 'Miễn phí'}</b></div><div className="flex justify-between text-[#71869d]"><span>Ưu đãi</span><b className="text-[#d44b2e]">Đã áp dụng</b></div></div><div className="flex items-end justify-between py-5"><span className="text-sm font-bold text-[#315575]">Tổng cộng</span><b className="text-2xl text-[#d44b2e]">{money(total)}</b></div><Link href="/checkout" className="block w-full bg-[#e65a37] py-3 text-center text-sm font-bold text-white transition hover:bg-[#cb4726]" data-testid="link-checkout">Tiến hành đặt hàng <ArrowRight size={16} className="ml-1 inline" /></Link><div className="mt-4 flex items-start gap-2 text-xs leading-5 text-[#71869d]"><ShieldCheck size={16} className="mt-0.5 shrink-0 text-[#168265]" /> Thông tin của bạn được bảo mật trong suốt quá trình đặt hàng.</div></div></div>}</main>;
}

function CheckoutPage({ ctx }: { ctx: StoreContext }) {
  const [method, setMethod] = useState('cod'); const [install, setInstall] = useState(true); const [submitted, setSubmitted] = useState(false); const [valid, setValid] = useState(false); const subtotal = ctx.cart.reduce((s, i) => s + i.product.price * i.qty, 0); const total = subtotal + (subtotal > 10000000 ? 0 : 35000) + (install ? 250000 : 0);
  if (submitted) return <SuccessPage ctx={ctx} />;
  return <main className="container-store py-8"><div className="mb-8 flex items-center justify-between"><div><div className="mb-1 text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">Bước cuối cùng</div><h1 className="font-display text-3xl font-bold text-[#14385f]">Đặt hàng</h1></div><div className="hidden items-center gap-2 text-xs font-semibold text-[#8293a8] sm:flex"><span className="text-[#0b4fa4]">01 Giỏ hàng</span><ChevronRight size={14} /><span className="text-[#0b4fa4]">02 Thông tin</span><ChevronRight size={14} /><span>03 Hoàn tất</span></div></div><div className="grid gap-7 lg:grid-cols-[1fr_360px]"><div className="space-y-5"><CheckoutBox title="Thông tin người nhận" icon={<UserRound size={18} />}><div className="grid gap-3 sm:grid-cols-2"><label className="text-sm text-[#5e7792]">Họ và tên<input className="mt-1 w-full border border-[#d5e1ec] px-3 py-2.5 text-sm outline-none focus:border-[#0b4fa4]" placeholder="Nguyễn Minh Anh" required data-testid="input-checkout-name" /></label><label className="text-sm text-[#5e7792]">Số điện thoại<input className="mt-1 w-full border border-[#d5e1ec] px-3 py-2.5 text-sm outline-none focus:border-[#0b4fa4]" placeholder="09xx xxx xxx" required data-testid="input-checkout-phone" /></label><label className="text-sm text-[#5e7792] sm:col-span-2">Địa chỉ nhận hàng<input className="mt-1 w-full border border-[#d5e1ec] px-3 py-2.5 text-sm outline-none focus:border-[#0b4fa4]" placeholder="Số nhà, đường, phường/xã..." required data-testid="input-checkout-address" /></label><label className="text-sm text-[#5e7792]">Tỉnh / thành phố<select className="mt-1 w-full border border-[#d5e1ec] bg-white px-3 py-2.5 text-sm outline-none" data-testid="select-checkout-city"><option>Hồ Chí Minh</option><option>Hà Nội</option><option>Đà Nẵng</option></select></label><label className="text-sm text-[#5e7792]">Ghi chú<input className="mt-1 w-full border border-[#d5e1ec] px-3 py-2.5 text-sm outline-none" placeholder="Giao giờ hành chính..." data-testid="input-checkout-note" /></label></div></CheckoutBox><CheckoutBox title="Giao hàng & lắp đặt" icon={<Truck size={18} />}><label className="flex cursor-pointer items-start gap-3 border border-[#c9dced] bg-[#f5f9fd] p-4"><input type="radio" checked readOnly className="mt-1 accent-[#0b4fa4]" /><span><b className="block text-sm text-[#214665]">Giao hàng tiêu chuẩn</b><span className="mt-1 block text-xs text-[#71869d]">Dự kiến giao trong 1–2 ngày · Miễn phí đơn từ 10 triệu</span></span></label><label className="mt-3 flex cursor-pointer items-start gap-3 border border-[#c9dced] p-4"><input type="checkbox" checked={install} onChange={(e) => setInstall(e.target.checked)} className="mt-1 accent-[#0b4fa4]" data-testid="checkbox-install" /><span><b className="block text-sm text-[#214665]">Đăng ký lắp đặt tận nơi <span className="text-[#d44b2e]">+250.000₫</span></b><span className="mt-1 block text-xs text-[#71869d]">Kỹ thuật viên gọi xác nhận lịch trước khi đến</span></span></label></CheckoutBox><CheckoutBox title="Phương thức thanh toán" icon={<CreditCard size={18} />}><div className="grid gap-3 sm:grid-cols-3">{[['cod', 'Tiền mặt khi nhận', 'COD'], ['bank', 'Chuyển khoản', 'NAPAS'], ['card', 'Thẻ tín dụng', 'VISA']].map(([key, label, badge]) => <label key={key} className={`cursor-pointer border p-4 ${method === key ? 'border-[#0b4fa4] bg-[#f2f7fd]' : 'border-[#dce5ef]'}`}><input type="radio" name="payment" checked={method === key} onChange={() => setMethod(key)} className="sr-only" data-testid={`radio-payment-${key}`} /><span className="flex items-center justify-between"><b className="text-sm text-[#315575]">{label}</b><span className="text-[10px] font-bold text-[#0b4fa4]">{badge}</span></span></label>)}</div></CheckoutBox></div><div className="h-fit border border-[#dce5ef] bg-white p-5 lg:sticky lg:top-28"><h2 className="font-display text-lg font-bold text-[#214665]">Đơn hàng của bạn</h2><div className="mt-4 space-y-3 border-b border-[#e1e8f0] pb-4">{ctx.cart.length ? ctx.cart.map((i) => <div key={i.product.id} className="flex gap-3 text-sm"><img src={i.product.image} alt="" className="h-14 w-14 object-cover mix-blend-multiply" /><div className="min-w-0 flex-1"><div className="line-clamp-2 text-xs font-semibold text-[#315575]">{i.product.name}</div><span className="text-xs text-[#8293a8]">SL: {i.qty}</span></div><b className="shrink-0 text-xs text-[#315575]">{money(i.product.price * i.qty)}</b></div>) : <p className="text-sm text-[#71869d]">Chưa có sản phẩm</p>}</div><div className="space-y-3 py-4 text-sm"><div className="flex justify-between text-[#71869d]"><span>Tạm tính</span><b>{money(subtotal)}</b></div><div className="flex justify-between text-[#71869d]"><span>Giao hàng</span><b>{subtotal > 10000000 ? 'Miễn phí' : money(35000)}</b></div><div className="flex justify-between text-[#71869d]"><span>Lắp đặt</span><b>{install ? money(250000) : '—'}</b></div></div><div className="flex items-end justify-between border-t border-[#e1e8f0] pt-4"><span className="font-bold text-[#315575]">Tổng thanh toán</span><b className="text-2xl text-[#d44b2e]">{money(total)}</b></div><button className="mt-5 w-full bg-[#e65a37] py-3.5 text-sm font-bold text-white disabled:cursor-not-allowed disabled:bg-[#b8c5d2]" disabled={!ctx.cart.length} onClick={() => { setValid(true); setTimeout(() => setSubmitted(true), 500); }} data-testid="button-place-order">{valid ? 'Đang tạo đơn hàng...' : 'Xác nhận đặt hàng'}</button><p className="mt-3 text-center text-[11px] leading-5 text-[#8293a8]">Bằng việc đặt hàng, bạn đồng ý với điều khoản mua bán của Điện Máy 365.</p></div></div></main>;
}
function CheckoutBox({ title, icon, children }: { title: string; icon: React.ReactNode; children: React.ReactNode }) { return <section className="border border-[#dce5ef] bg-white p-5"><h2 className="mb-5 flex items-center gap-2 font-display text-lg font-bold text-[#214665]">{icon}<span>{title}</span></h2>{children}</section>; }

function SuccessPage({ ctx }: { ctx: StoreContext }) { return <main className="container-store flex min-h-[620px] items-center justify-center py-10"><div className="w-full max-w-xl border border-[#cce4da] bg-white p-7 text-center shadow-[0_15px_35px_rgba(13,99,72,.08)] sm:p-12"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#e4f5ee] text-[#168265]"><Check size={32} /></div><div className="mt-5 text-xs font-bold uppercase tracking-[.2em] text-[#168265]">Đặt hàng thành công</div><h1 className="mt-2 font-display text-3xl font-bold text-[#14385f]">Cảm ơn bạn đã mua sắm!</h1><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-[#71869d]">Đơn hàng <b className="text-[#214665]">DM365-240619-582</b> đã được ghi nhận. Nhân viên sẽ gọi xác nhận trong 15 phút.</p><div className="mt-7 grid gap-3 border-y border-[#e1e8f0] py-5 text-left text-sm sm:grid-cols-2"><div><span className="block text-xs text-[#8293a8]">Dự kiến giao hàng</span><b className="mt-1 block text-[#315575]">19–20/06/2024</b></div><div><span className="block text-xs text-[#8293a8]">Thanh toán</span><b className="mt-1 block text-[#315575]">Tiền mặt khi nhận hàng</b></div></div><div className="mt-7 flex flex-col gap-3 sm:flex-row"><button className="flex-1 border border-[#0b4fa4] py-3 text-sm font-bold text-[#0b4fa4]" onClick={() => alert('Mã tra cứu: DM365-240619-582')} data-testid="button-track-order"><PackageCheck size={16} className="mr-1 inline" /> Tra cứu đơn hàng</button><Link href="/products" className="flex-1 bg-[#0b4fa4] py-3 text-sm font-bold text-white" data-testid="link-success-shop">Tiếp tục mua sắm</Link></div></div></main>; }

function AccountPage({ ctx }: { ctx: StoreContext }) { const [tab, setTab] = useState('orders'); const tabs = [['orders', 'Đơn hàng của tôi'], ['wishlist', `Yêu thích (${ctx.wishlist.length})`], ['viewed', 'Đã xem gần đây'], ['profile', 'Thông tin tài khoản']]; const wishProducts = products.filter((p) => ctx.wishlist.includes(p.id)); return <main className="container-store py-8"><div className="mb-8 flex items-center gap-4"><div className="grid h-16 w-16 place-items-center bg-[#dcecff] font-display text-xl font-bold text-[#0b4fa4]">MA</div><div><div className="text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">Xin chào</div><h1 className="font-display text-2xl font-bold text-[#14385f]">Minh Anh</h1><p className="text-sm text-[#71869d]">Thành viên bạc · 365 điểm tích lũy</p></div></div><div className="grid gap-8 lg:grid-cols-[220px_1fr]"><aside className="flex gap-2 overflow-x-auto lg:block lg:space-y-1">{tabs.map(([key, label]) => <button key={key} className={`shrink-0 border-b-2 px-3 py-3 text-left text-sm font-semibold lg:block lg:w-full lg:border-b-0 ${tab === key ? 'border-[#0b4fa4] bg-[#eaf3ff] text-[#0b4fa4]' : 'border-transparent text-[#71869d] hover:bg-[#f1f6fb]'}`} onClick={() => setTab(key)} data-testid={`button-account-${key}`}>{label}</button>)}<button className="hidden w-full border-t border-[#e1e8f0] px-3 py-3 text-left text-sm font-semibold text-[#d44b2e] lg:block" onClick={() => alert('Đã đăng xuất khỏi bản demo')} data-testid="button-account-logout">Đăng xuất</button></aside><div>{tab === 'orders' && <section><SectionTitle title="Đơn hàng gần đây" /><div className="border border-[#dce5ef] bg-white">{orders.slice(0, 5).map((o) => <div key={o.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e5ebf2] p-4 last:border-0"><div><div className="text-xs font-bold text-[#0b4fa4]">{o.id}</div><div className="mt-1 text-sm font-semibold text-[#315575]">{o.items[0]}</div><div className="mt-1 text-xs text-[#8293a8]">{o.date} · {money(o.total)}</div></div><span className={`px-2 py-1 text-xs font-bold ${o.status === 'Đang giao' ? 'bg-[#eaf3ff] text-[#0b4fa4]' : 'bg-[#e5f5ee] text-[#168265]'}`}>{o.status}</span></div>)}</div></section>}{tab === 'wishlist' && <section><SectionTitle title="Sản phẩm yêu thích" /><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{wishProducts.length ? wishProducts.map((p) => <ProductCard key={p.id} product={p} ctx={ctx} />) : <div className="col-span-full"><EmptyState onClear={() => setTab('orders')} /></div>}</div></section>}{tab === 'viewed' && <section><SectionTitle title="Đã xem gần đây" /><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{products.slice(2, 5).map((p) => <ProductCard key={p.id} product={p} ctx={ctx} />)}</div></section>}{tab === 'profile' && <section className="border border-[#dce5ef] bg-white p-5"><SectionTitle title="Thông tin tài khoản" /><div className="grid gap-4 sm:grid-cols-2"><ProfileField label="Họ và tên" value="Nguyễn Minh Anh" /><ProfileField label="Số điện thoại" value="090 123 4567" /><ProfileField label="Email" value="minhanh@example.com" /><ProfileField label="Địa chỉ mặc định" value="24 Nguyễn Hữu Cảnh, Bình Thạnh, TP.HCM" /></div><button className="mt-6 bg-[#0b4fa4] px-5 py-3 text-sm font-bold text-white" onClick={() => alert('Thông tin đã được cập nhật')} data-testid="button-account-save">Lưu thay đổi</button></section>}</div></div></main>; }
function ProfileField({ label, value }: { label: string; value: string }) { return <label className="text-sm text-[#71869d]">{label}<input defaultValue={value} className="mt-1 w-full border border-[#d5e1ec] px-3 py-2.5 text-sm text-[#315575] outline-none focus:border-[#0b4fa4]" data-testid={`input-profile-${label}`} /></label>; }

function NewsPage() { return <main className="container-store py-8"><div className="mb-8"><div className="mb-1 text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">Góc tư vấn</div><h1 className="font-display text-4xl font-bold tracking-tight text-[#14385f]">Mua đúng, dùng hay</h1><p className="mt-3 max-w-xl text-sm leading-6 text-[#71869d]">Kinh nghiệm chọn mua, sử dụng và bảo quản thiết bị điện máy từ đội ngũ Điện Máy 365.</p></div><div className="grid gap-x-5 gap-y-9 sm:grid-cols-2 lg:grid-cols-3">{articles.map((a, i) => <Link href={`/news/${a.id}`} key={a.id} className={`group ${i === 0 ? 'sm:col-span-2 lg:col-span-2' : ''}`} data-testid={`link-article-${a.id}`}><div className="relative overflow-hidden bg-[#eaf3ff]"><img src={a.image} alt="" className={`w-full object-cover mix-blend-multiply transition duration-500 group-hover:scale-105 ${i === 0 ? 'aspect-[2/1]' : 'aspect-[1.5/1]'}`} /><span className="absolute left-3 top-3 bg-white/90 px-2 py-1 text-[10px] font-bold uppercase tracking-wider text-[#0b4fa4]">{a.category}</span></div><div className="mt-3 text-[11px] text-[#8293a8]">{a.date} · {a.read} đọc</div><h2 className="mt-1 font-display text-lg font-bold leading-6 text-[#214665] group-hover:text-[#0b4fa4]">{a.title}</h2><p className="mt-2 line-clamp-2 text-sm leading-6 text-[#71869d]">{a.excerpt}</p></Link>)}</div></main>; }
function ArticlePage() { const { id } = useParams<{ id: string }>(); const article = articles.find((a) => a.id === id) ?? articles[0]; return <main className="container-store py-8"><Link href="/news" className="mb-6 inline-flex items-center gap-1 text-sm font-semibold text-[#0b4fa4]" data-testid="link-article-back"><ArrowLeft size={15} /> Quay lại chuyên mục</Link><article className="mx-auto max-w-4xl"><div className="text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">{article.category} · {article.date}</div><h1 className="mt-3 font-display text-3xl font-bold leading-tight text-[#14385f] sm:text-5xl">{article.title}</h1><p className="mt-4 max-w-2xl text-base leading-7 text-[#71869d]">{article.excerpt}</p><img src={article.image} alt="" className="mt-8 aspect-[2/1] w-full object-cover mix-blend-multiply" /><div className="prose prose-slate mt-8 max-w-2xl text-[#4d6984]"><p>Chọn một thiết bị điện máy tốt không chỉ là nhìn vào mức giá. Kích thước không gian, tần suất sử dụng và thói quen của gia đình mới là nền tảng để quyết định đúng.</p><h2>Đo nhu cầu trước khi đo giá</h2><p>Hãy bắt đầu từ những điều rất cụ thể: căn phòng rộng bao nhiêu, có nắng chiếu trực tiếp không, gia đình có trẻ nhỏ hay người lớn tuổi không. Mỗi câu trả lời sẽ đưa bạn đến nhóm sản phẩm phù hợp hơn.</p><blockquote>Thiết bị tốt là thiết bị vừa vặn với nhịp sống của gia đình bạn.</blockquote><h2>Ba chi tiết nên kiểm tra</h2><p>Thông số tiêu thụ điện, chính sách bảo hành và dịch vụ sau bán hàng là ba điểm thường bị bỏ qua. Tại Điện Máy 365, đội ngũ tư vấn giúp bạn xem cả chi phí dùng dài hạn trước khi quyết định.</p></div></article><div className="mx-auto mt-14 max-w-4xl"><SectionTitle title="Sản phẩm trong bài viết" /><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{products.slice(0, 4).map((p) => <ProductCard key={p.id} product={p} ctx={demoContext} />)}</div></div></main>; }

function AdminPage() { const [range, setRange] = useState('7'); return <main className="bg-[#eef3f8]"><div className="container-store py-7"><div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><div className="mb-1 text-xs font-bold uppercase tracking-[.2em] text-[#c37c0c]">Khu vực nội bộ</div><h1 className="font-display text-3xl font-bold text-[#14385f]">Tổng quan vận hành</h1><p className="mt-1 text-sm text-[#71869d]">Cập nhật lần cuối: hôm nay, 09:42</p></div><button className="flex items-center gap-2 border border-[#cbd9e7] bg-white px-3 py-2 text-sm font-semibold text-[#315575]" onClick={() => alert('Đã làm mới dữ liệu')} data-testid="button-admin-refresh"><Bell size={15} /> Làm mới dữ liệu</button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Doanh thu hôm nay" value="284,6 triệu" change="+12,8%" icon={<Wallet />} /><Metric label="Đơn hàng mới" value="47 đơn" change="+8,2%" icon={<PackageCheck />} /><Metric label="Giá trị đơn TB" value="6,04 triệu" change="+3,4%" icon={<BarChart3 />} /><Metric label="Tỷ lệ chuyển đổi" value="4,72%" change="+0,6%" icon={<Zap />} /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.5fr_1fr]"><section className="border border-[#d8e3ed] bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold text-[#214665]">Doanh thu theo thời gian</h2><p className="mt-1 text-xs text-[#8293a8]">Tổng doanh thu · đồng</p></div><select value={range} onChange={(e) => setRange(e.target.value)} className="border border-[#d5e1ec] bg-white px-2 py-1.5 text-xs" data-testid="select-admin-range"><option value="7">7 ngày qua</option><option value="30">30 ngày qua</option><option value="90">Quý này</option></select></div><div className="mt-8 flex h-52 items-end gap-2 border-b border-l border-[#dce5ef] px-3 pb-0 pt-4">{[42, 58, 47, 74, 61, 86, 68, 92, 77, 100, 83, 95].map((h, i) => <div key={i} className="group relative flex flex-1 items-end h-full"><div style={{ height: `${h}%` }} className="w-full bg-[#b9d6f3] transition group-hover:bg-[#0b4fa4]"></div><span className="absolute -bottom-5 left-1/2 -translate-x-1/2 text-[9px] text-[#8293a8]">{i + 1}</span></div>)}</div><div className="mt-8 flex justify-between text-xs text-[#8293a8]"><span>18/06</span><span>Hôm nay</span></div></section><section className="border border-[#d8e3ed] bg-white p-5"><div className="flex items-center justify-between"><h2 className="font-display text-lg font-bold text-[#214665]">Sản phẩm sắp hết</h2><Link href="/products" className="text-xs font-bold text-[#0b4fa4]" data-testid="link-admin-inventory">Quản lý kho</Link></div><div className="mt-5 space-y-4">{products.slice(0, 5).map((p, i) => <div key={p.id} className="flex items-center gap-3"><img src={p.image} alt="" className="h-12 w-12 object-cover mix-blend-multiply" /><div className="min-w-0 flex-1"><div className="line-clamp-1 text-xs font-bold text-[#315575]">{p.name}</div><div className="mt-1 h-1.5 bg-[#edf1f5]"><div className={`h-full ${i < 2 ? 'bg-[#e55937]' : 'bg-[#e8aa19]'}`} style={{ width: `${Math.max(12, p.stock * 5)}%` }}></div></div></div><span className={`text-xs font-bold ${i < 2 ? 'text-[#d44b2e]' : 'text-[#b57a0b]'}`}>{p.stock} chiếc</span></div>)}</div></section></div><section className="mt-6 border border-[#d8e3ed] bg-white p-5"><div className="flex items-center justify-between"><h2 className="font-display text-lg font-bold text-[#214665]">Đơn hàng gần đây</h2><button className="text-xs font-bold text-[#0b4fa4]" onClick={() => alert('Đang hiển thị tất cả đơn hàng')} data-testid="button-admin-orders">Xem tất cả</button></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead><tr className="border-b border-[#e1e8f0] text-xs uppercase tracking-wider text-[#8293a8]"><th className="pb-3">Mã đơn</th><th className="pb-3">Sản phẩm</th><th className="pb-3">Ngày đặt</th><th className="pb-3">Tổng tiền</th><th className="pb-3">Trạng thái</th></tr></thead><tbody>{orders.slice(0, 6).map((o) => <tr key={o.id} className="border-b border-[#edf1f5] last:border-0"><td className="py-4 font-bold text-[#0b4fa4]">{o.id}</td><td className="py-4 text-[#315575]">{o.items[0]}</td><td className="py-4 text-[#71869d]">{o.date}</td><td className="py-4 font-bold text-[#315575]">{money(o.total)}</td><td className="py-4"><span className={`px-2 py-1 text-xs font-bold ${o.status === 'Đang giao' ? 'bg-[#eaf3ff] text-[#0b4fa4]' : 'bg-[#e5f5ee] text-[#168265]'}`}>{o.status}</span></td></tr>)}</tbody></table></div></section><div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4">{['Sản phẩm', 'Đơn hàng', 'Khách hàng', 'Khuyến mãi'].map((x, i) => <button key={x} className="flex items-center gap-3 border border-[#d8e3ed] bg-white p-4 text-left transition hover:border-[#8eb4db]" onClick={() => alert(`Mở quản lý ${x.toLowerCase()}`)} data-testid={`button-admin-${i}`}><span className="grid h-9 w-9 place-items-center bg-[#eaf3ff] text-[#0b4fa4]">{i === 0 ? <Box size={17} /> : i === 1 ? <PackageCheck size={17} /> : i === 2 ? <UserRound size={17} /> : <Tag size={17} />}</span><span><b className="block text-sm text-[#315575]">{x}</b><small className="text-[10px] text-[#8293a8]">Quản lý ngay</small></span></button>)}</div></div></main>; }
function Metric({ label, value, change, icon }: { label: string; value: string; change: string; icon: React.ReactNode }) { return <div className="border border-[#d8e3ed] bg-white p-4"><div className="flex items-start justify-between"><span className="grid h-9 w-9 place-items-center bg-[#eaf3ff] text-[#0b4fa4]">{icon}</span><span className="text-xs font-bold text-[#168265]">{change}</span></div><div className="mt-4 text-xs text-[#8293a8]">{label}</div><b className="mt-1 block font-display text-2xl text-[#214665]">{value}</b></div>; }

function QuickViewModal({ product, ctx, close }: { product: Product; ctx: StoreContext; close: () => void }) { return <div className="fixed inset-0 z-[60] grid place-items-center bg-[#102c4b]/45 p-4" onClick={close}><div className="w-full max-w-2xl bg-white p-5 shadow-2xl sm:p-7" onClick={(e) => e.stopPropagation()}><div className="mb-4 flex justify-end"><button onClick={close} className="text-[#8293a8]" data-testid="button-close-quickview"><X /></button></div><div className="grid gap-6 sm:grid-cols-2"><img src={product.image} alt={product.name} className="aspect-square w-full object-cover mix-blend-multiply" /><div><div className="text-xs font-bold uppercase tracking-wider text-[#8294a9]">{product.brand}</div><h2 className="mt-2 font-display text-xl font-bold text-[#214665]">{product.name}</h2><div className="mt-4 text-2xl font-extrabold text-[#d44b2e]">{money(product.price)}</div><div className="mt-4 space-y-2">{product.specs.slice(0, 3).map((s) => <div key={s.label} className="flex justify-between border-b border-dashed border-[#e1e8f0] py-2 text-sm"><span className="text-[#71869d]">{s.label}</span><b className="text-[#315575]">{s.value}</b></div>)}</div><button className="mt-6 w-full bg-[#0b4fa4] py-3 text-sm font-bold text-white" onClick={() => { ctx.addToCart(product); close(); }} data-testid={`button-quick-add-${product.id}`}>Thêm vào giỏ hàng</button><Link href={`/products/${product.id}`} onClick={close} className="mt-3 block text-center text-sm font-bold text-[#0b4fa4]" data-testid={`link-quick-detail-${product.id}`}>Xem chi tiết</Link></div></div></div></div>; }

function BottomNav({ ctx }: { ctx: StoreContext }) {
  const [loc] = useLocation();
  const items: { icon: React.ComponentType<{ size?: number }>; label: string; href: string }[] = [
    { icon: Home, label: 'Trang chủ', href: '/' },
    { icon: Search, label: 'Khám phá', href: '/products' },
    { icon: Heart, label: 'Yêu thích', href: '/account' },
    { icon: ShoppingCart, label: 'Giỏ hàng', href: '/cart' },
  ];
  return <nav className="fixed bottom-0 left-0 right-0 z-40 grid grid-cols-4 border-t border-[#dce5ef] bg-white/95 py-2 backdrop-blur md:hidden">{items.map(({ icon: Icon, label, href }) => <Link key={label} href={href} className={`relative flex flex-col items-center gap-1 text-[10px] font-semibold ${(loc === href || (href !== '/' && loc.startsWith(href))) ? 'text-[#0b4fa4]' : 'text-[#8293a8]'}`} data-testid={`bottom-nav-${label}`}><Icon size={18} /><span>{label}</span>{label === 'Giỏ hàng' && ctx.cart.length ? <span className="absolute left-1/2 top-0 ml-1 grid h-3 min-w-3 place-items-center bg-[#e55937] px-0.5 text-[8px] text-white">{ctx.cart.length}</span> : null}</Link>)}</nav>;
}

function NotFound() { return <main className="container-store flex min-h-[500px] flex-col items-center justify-center text-center"><div className="font-display text-7xl font-bold text-[#c7dcef]">404</div><h1 className="mt-3 font-display text-2xl font-bold text-[#214665]">Trang này chưa có</h1><Link href="/" className="mt-5 bg-[#0b4fa4] px-5 py-3 text-sm font-bold text-white" data-testid="link-notfound-home">Về trang chủ</Link></main>; }

const demoContext: StoreContext = { cart: [], wishlist: [], compared: [], toggleWishlist: () => undefined, toggleCompare: () => undefined, addToCart: () => undefined, updateQty: () => undefined, removeCart: () => undefined, openQuickView: () => undefined };

function AppShell() {
  const [cart, setCart] = useState<CartItem[]>([]); const [wishlist, setWishlist] = useState<string[]>(['ac-02']); const [compared, setCompared] = useState<string[]>([]); const [quickView, setQuickView] = useState<Product | null>(null);
  const ctx: StoreContext = { cart, wishlist, compared, toggleWishlist: (id) => setWishlist((v) => v.includes(id) ? v.filter((x) => x !== id) : [...v, id]), toggleCompare: (id) => setCompared((v) => v.includes(id) ? v.filter((x) => x !== id) : v.length >= 4 ? v : [...v, id]), addToCart: (product, qty = 1) => setCart((items) => items.some((i) => i.product.id === product.id) ? items.map((i) => i.product.id === product.id ? { ...i, qty: i.qty + qty } : i) : [...items, { product, qty }]), updateQty: (id, qty) => setCart((items) => qty < 1 ? items.filter((i) => i.product.id !== id) : items.map((i) => i.product.id === id ? { ...i, qty } : i)), removeCart: (id) => setCart((items) => items.filter((i) => i.product.id !== id)), openQuickView: setQuickView };
  return <div className="texture min-h-[100dvh] pb-16 md:pb-0"><Header ctx={ctx} /><Switch><Route path="/" component={() => <HomePage ctx={ctx} />} /><Route path="/products" component={() => <ProductsPage ctx={ctx} />} /><Route path="/products/:id" component={() => <ProductDetail ctx={ctx} />} /><Route path="/compare" component={() => <ComparePage ctx={ctx} />} /><Route path="/cart" component={() => <CartPage ctx={ctx} />} /><Route path="/checkout" component={() => <CheckoutPage ctx={ctx} />} /><Route path="/order-success" component={() => <SuccessPage ctx={ctx} />} /><Route path="/account" component={() => <AccountPage ctx={ctx} />} /><Route path="/news" component={NewsPage} /><Route path="/news/:id" component={ArticlePage} /><Route path="/admin" component={AdminPage} /><Route component={NotFound} /></Switch><Footer /><BottomNav ctx={ctx} />{quickView && <QuickViewModal product={quickView} ctx={ctx} close={() => setQuickView(null)} />}</div>;
}

export default AppShell;